export function deriveSelectedAttributesFromProduct(product = {}) {
  const attrs = [];
  const ags = Array.isArray(product.attributeGroups) ? product.attributeGroups : [];

  for (const g of ags) {
    if (!g) continue;
    const groupKey = g.key || g.title || '';
    if (g.type === 'single-select') {
      // include a default only if explicitly marked and group is not optional
      const def = (g.attributes || []).find(a => a && (a.defaultSelected === true));
      if (def && !g.optional) {
        attrs.push({
          groupKey,
          id: def._id || def.id,
          name: def.name,
          priceType: def.priceType || 'flat',
          amount: def.amount || 0,
          quantity: 1
        });
      }
    } else if (g.type === 'multi-select') {
      for (const a of (g.attributes || [])) {
        if (a && a.defaultSelected) {
          attrs.push({
            groupKey,
            id: a._id || a.id,
            name: a.name,
            priceType: a.priceType || 'flat',
            amount: a.amount || 0,
            quantity: a.quantityEnabled ? (a.defaultQuantity || 1) : 1
          });
        }
      }
    }
  }

  return attrs;
}
