import React, { useEffect, useState } from 'react';
import axios from 'axios';
import api from '../utils/apiClient';
import { FiX } from 'react-icons/fi';
import StarRating from './StarRating';
import LoadingSpinner from './LoadingSpinner';
import { useAuth } from '../context/AuthContext';

export default function DriverModal({ driverId, isOpen, onClose, orderId = null }) {
  const { user } = useAuth();
  const [driver, setDriver] = useState(null);
  const [ratings, setRatings] = useState([]);
  const [page, setPage] = useState(1);
  const [pages, setPages] = useState(1);
  const [loading, setLoading] = useState(false);
  const [myRating, setMyRating] = useState({ rating: 0, text: '' });
  const [canRate, setCanRate] = useState(null);
  const API = process.env.REACT_APP_API_URL || 'http://localhost:5000';

  useEffect(() => {
    if (!isOpen) return;
    // clear draft rating when modal opens
    setMyRating({ rating: 0, text: '' });
    let mounted = true;
    (async () => {
      try {
        setLoading(true);
        const [driverRes, ratingsRes] = await Promise.all([
          api.get(`/users/${driverId}`),
          api.get(`/ratings`, { params: { entityType: 'driver', entityId: driverId, page, pageSize: 5 } })
        ]);
        if (!mounted) return;
        setDriver(driverRes.data.user || driverRes.data);
        const data = ratingsRes.data || {};
        setRatings(data.reviews || data.items || []);
        setPages(data.pagination ? data.pagination.pages : 1);
        if (typeof data.canRate !== 'undefined') setCanRate(Boolean(data.canRate));
      } catch (e) {
        console.error('Failed to load driver modal', e);
      } finally { if (mounted) setLoading(false); }
    })();
    return () => { mounted = false; };
  }, [isOpen, driverId, page, API]);

  const openMapsForAddress = (addr) => {
    try {
      const q = encodeURIComponent(addr || "");
      window.open(`https://www.google.com/maps/search/?api=1&query=${q}`, "_blank");
    } catch (e) {}
  };

  const submitRating = async () => {
    if (!orderId) {
      // require order context to submit ratings
      return;
    }
    try {
      await axios.post(`${API}/api/ratings`, { entityType: 'driver', entityId: driverId, rating: myRating.rating, text: myRating.text, orderId });
      setPage(1);
    } catch (e) {
      console.error('Failed to submit rating', e);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-content" onClick={(e) => e.stopPropagation()} style={{ maxWidth: 760 }}>
        <div className="modal-header">
          <h2>Driver</h2>
          <button className="modal-close" onClick={() => { setMyRating({ rating: 0, text: '' }); onClose && onClose(); }} aria-label="Close">
            <FiX size={20} />
          </button>
        </div>
        <div className="modal-body">
          {loading ? <div style={{ textAlign: 'center', padding: 24 }}><LoadingSpinner /></div> : (
            <div>
              <div>
                <div style={{ display: 'flex', gap: 12, alignItems: 'center' }}>
                  <div style={{ width: 72, height: 72, borderRadius: 8, background: '#f4f4f4', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                    {driver?.avatar ? <img src={driver.avatar} alt="driver" style={{ width: '100%', height: '100%', objectFit: 'cover' }} /> : <div style={{ fontSize: 28 }}>🚗</div>}
                  </div>
                  <div>
                    <div style={{ color: '#666', marginTop: 0 }}>{driver?.driverProfile?.location || 'Not set'}</div>
                  </div>
                </div>

                <div className="details-grid" style={{ marginTop: 12 }}>
                  <div className="detail-item">
                    <div className="detail-content">
                      <span className="detail-label">Name</span>
                      <span className="detail-value">{driver?.displayName || driver?.name || 'Not set'}</span>
                    </div>
                  </div>
                  <div className="detail-item">
                    <div className="detail-content">
                      <span className="detail-label">Vehicle Number</span>
                      <span className="detail-value">{driver?.driverProfile?.vehicleNumber ? 'Hidden' : 'Not set'}</span>
                    </div>
                  </div>
                  <div className="detail-item">
                    <div className="detail-content">
                      <span className="detail-label">Phone</span>
                      <span className="detail-value">{driver?.phone || 'Not set'}</span>
                    </div>
                  </div>
                  <div className="detail-item">
                    <div className="detail-content">
                      <span className="detail-label">Location</span>
                      <span className="detail-value" style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                        <span>{driver?.driverProfile?.location || 'Not set'}</span>
                        {driver?.driverProfile?.location ? (
                          <button className="btn btn-icon" onClick={() => openMapsForAddress(driver?.driverProfile?.location)} aria-label="Open in maps">
                            <svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 10c0 7-9 13-9 13S3 17 3 10a9 9 0 0 1 18 0z"/><circle cx="12" cy="10" r="3"/></svg>
                          </button>
                        ) : null}
                      </span>
                    </div>
                  </div>
                  <div className="detail-item">
                    <div className="detail-content">
                      <span className="detail-label">Email</span>
                      <span className="detail-value">{driver?.email || 'Not set'}</span>
                    </div>
                  </div>
                </div>
              </div>

              <div style={{ height: 1, background: 'var(--border-color)', margin: '16px 0' }} />

              <div className="form-group">
                <h4 style={{ margin: 0, marginBottom: 8 }}>Leave a rating</h4>
                {canRate === false && (
                  <div style={{ color: 'var(--danger-color, #d32f2f)', padding: 8, borderRadius: 6, background: 'rgba(211,47,47,0.05)' }}>
                    Ratings are limited to users who participated in a delivered order involving this driver. Please rate from your order details or the delivered order notification.
                  </div>
                )}
                {canRate !== false && (
                  <div style={{ display: 'flex', gap: 12, alignItems: 'center' }}>
                    <StarRating value={myRating.rating} onChange={(v) => setMyRating((s) => ({ ...s, rating: v }))} interactive={true} size={22} />
                    <textarea placeholder="Leave a short comment (optional)" value={myRating.text} onChange={(e) => setMyRating((s) => ({ ...s, text: e.target.value }))} style={{ flex: 1, minHeight: 80 }} />
                  </div>
                )}
              </div>

              <div style={{ height: 1, background: 'var(--border-color)', margin: '16px 0' }} />

              <div className="form-group">
                <h4 style={{ margin: 0, marginBottom: 8 }}>Ratings</h4>
                {ratings.length === 0 ? <p style={{ margin: 0 }}>No ratings yet</p> : (
                  <div>
                    {ratings.map(r => (
                      <div key={r._id} style={{ borderBottom: '1px solid #eee', padding: '12px 0' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                          <div style={{ fontWeight: 600 }}>{r.user?.displayName || r.user?.name || 'User'}</div>
                          <div><StarRating value={r.rating} interactive={false} size={16} /></div>
                        </div>
                        {r.text && <div style={{ marginTop: 8 }}>{r.text}</div>}
                        <div style={{ color: '#999', fontSize: 12, marginTop: 8 }}>{new Date(r.createdAt).toLocaleString()}</div>
                      </div>
                    ))}

                    <div style={{ marginTop: 12 }}>
                      <button disabled={page <= 1} onClick={() => setPage(p => Math.max(1, p - 1))} className="btn">Prev</button>
                      <span style={{ margin: '0 8px' }}>{page} / {pages}</span>
                      <button disabled={page >= pages} onClick={() => setPage(p => Math.min(pages, p + 1))} className="btn">Next</button>
                    </div>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
        <div className="modal-footer">
          <button onClick={() => { setMyRating({ rating: 0, text: '' }); onClose && onClose(); }} className="btn btn-cancel">Cancel</button>
          <button onClick={submitRating} className="btn btn-submit" disabled={canRate === false}>Submit</button>
        </div>
      </div>
    </div>
  );
}
